use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

/// The hosts this node's `with` clause grants. Checking them here keeps an
/// out-of-scope URL from trapping the whole run at the boundary; the host's
/// own allowlist remains the authority.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Returns true only for http(s) URLs whose host is exactly in the allowlist.
/// Rejects userinfo (`@`), backslashes, and whitespace/control characters, so
/// that parser differences cannot make a URL look allowed here and resolve
/// elsewhere.
fn in_scope(url: &str) -> bool {
    let rest = match url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))
    {
        Some(rest) => rest,
        None => return false,
    };

    let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
    if authority.contains(['@', '\\'])
        || authority.chars().any(|c| c.is_whitespace() || c.is_control())
    {
        return false;
    }

    let host = authority.split(':').next().unwrap_or("");
    ALLOWED_HOSTS
        .iter()
        .any(|allowed| allowed.eq_ignore_ascii_case(host))
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received, under the granted state store.
        // Done first so the record exists even if fetching later fails.
        let recorded = subscriptions.urls.join("\n");
        state_rw::put("last-input", &recorded);

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !in_scope(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url outside node scope".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
